def list_domains(): return deepcopy(list(BUSINESS_DOMAINS))
def get_domain(domain_id):
 k=domain_id.strip().casefold(); return next((deepcopy(x) for x in BUSINESS_DOMAINS if x["domain_id"].casefold()==k),None)
def search_domains(keyword):
 k=keyword.strip().casefold(); return [deepcopy(x) for x in BUSINESS_DOMAINS if k and k in " ".join(x.values()).casefold()]
def validate_mappings():
 ids=[x["domain_id"] for x in BUSINESS_DOMAINS]; core={x["domain_id"] for x in canonical_domains()}; missing=sorted({x["core_domain_id"] for x in BUSINESS_DOMAINS}-core)
 return {"valid":len(ids)==len(set(ids)) and not missing,"count":len(ids),"unique_ids":len(ids)==len(set(ids)),"missing_core_domain_ids":missing}
